update public.content_variants set body_id = $json${"type":"calculation","answer":"20","question":"Sebuah saham diperdagangkan pada Rp 20.000 dengan EPS Rp 1.000. Berapa rasio P/E-nya?","difficulty":"beginner","parameters":{"hint":"Bagilah harga saham dengan laba per saham."},"explanation":"P/E = Harga per saham / Laba per saham = 20.000 / 1.000 = 20."}$json$::jsonb where body_id = $json${"type":"calculation","answer":"20","question":"Sebuah saham diperdagangkan pada Rp 20.000 dengan EPS Rp 1.000. Berapa rasio P/E-nya?","difficulty":"beginner","parameters":{"hint":"Divide stock price by earnings per share."},"explanation":"P/E = Harga per saham / Laba per saham = 20.000 / 1.000 = 20."}$json$::jsonb;
