update public.content_variants set body_id = $json${"type":"calculation","answer":"8,4%","question":"Jika Rp 100M tumbuh menjadi Rp 150M dalam 5 tahun, berapa perkiraan tingkat pertumbuhan tahunan majemuk (CAGR)?","difficulty":"beginner","parameters":{"hint":"Gunakan rumus CAGR: (FV/PV)^(1/tahun) - 1."},"explanation":"CAGR = (Nilai Akhir / Nilai Awal)^(1/n) - 1 = (150/100)^(1/5) - 1 ≈ 8,4%."}$json$::jsonb where body_id = $json${"type":"calculation","answer":"8,4%","question":"Jika Rp 100M tumbuh menjadi Rp 150M dalam 5 tahun, berapa perkiraan tingkat pertumbuhan tahunan majemuk (CAGR)?","difficulty":"beginner","parameters":{"hint":"Use the CAGR formula: (FV/PV)^(1/years) - 1."},"explanation":"CAGR = (Nilai Akhir / Nilai Awal)^(1/n) - 1 = (150/100)^(1/5) - 1 ≈ 8,4%."}$json$::jsonb;
